"""FlowPilot AI — HARDENING TIER 1 apply engine.

Brings a tree at commit 960dd4d ("ARCH 40 DONE") to the hardened state:
107 file operations (modify / add / delete) across backend and frontend.

Run from the repository root (the folder holding backend/ and frontend/):

    python apply_hardening_tier1.py --check      # verify every file; write nothing
    python apply_hardening_tier1.py              # apply (atomic, with backup)
    python apply_hardening_tier1.py              # second run: reports no changes
    python apply_hardening_tier1.py --rollback   # restore the latest backup

SAFETY
  * Every modified or deleted file must match its 960dd4d content (sha256 over
    text with CRLF normalised to LF and any UTF-8 BOM removed), or already
    match the hardened content. Anything else is a CONFLICT and nothing is
    written — local edits are never overwritten.
  * All files are checked before any is written. Originals are copied to
    .hardening_t1_apply_backup/<timestamp>/ first; a failure mid-write
    restores them.
  * Line endings: a modified file keeps the style it has on disk (CRLF on a
    Windows checkout). New files use CRLF on Windows, LF elsewhere. Python
    files are written without a BOM.
"""

